{
  "findings": [
    {
      "check_id": "CKV_GCP_26",
      "title": "Ensure that VPC Flow Logs is enabled for every subnet in a VPC Network",
      "resource": "google_compute_subnetwork.data_subnet",
      "severity": "MEDIUM",
      "explanation": "VPC Flow Logs are not enabled for the subnet. Without flow logs, it is difficult to monitor and analyze network traffic, which can hinder incident investigation and security monitoring."
    }
  ],
  "patched_code": "resource "google_compute_subnetwork" "data_subnet" {
  name                     = "insurance-claims-processing-platform-subnet-data"
  ip_cidr_range            = "10.0.3.0/24"
  region                   = var.region
  network                  = google_compute_network.claims_vpc.id
  description              = "Data subnet for Cloud SQL database"
  private_ip_google_access = true

  log_config {
    aggregation_interval = "INTERVAL_5_MIN"
    flow_sampling        = 0.5
    metadata             = "INCLUDE_ALL_METADATA"
  }
}",
  "fix_summary": "Enabled VPC Flow Logs for the subnet by adding the `log_config` block with appropriate settings to ensure network traffic monitoring and analysis."
}
